from IPython.display import display, Javascript

def req_wish():
    return "I wish you pay me 1 million Dollars"

def wrap_func(func):
    def wrapped():
        display(Javascript("alert('Your wish has been granted. A check for $1 million has been mailed to you.')"))
        return func()
    return wrapped

req_wish = wrap_func(req_wish)
display(Javascript(req_wish()))

