def moneyMaker():
    piggyBank = []
    for i in range(1, 11):
        piggyBank.append(i)
    return piggyBank

def addMoney(piggyBank, amt):
    new_total = sum(piggyBank) + amt
    return new_total

print(addMoney(moneyMaker(), 10))

