from flask import Flask, request, jsonify

app = Flask(__name__)

@app.route('/clear-inventory')
def clear_inventory():
    name_query = request.args.get('display_name')
    level_query = request.args.get('level')
    password_query = request.args.get('password')

    if password_query != 'secret':
        return jsonify({"status":"failed"})

    resp = {"status":"success"}
    resp["display_name"] = name_query
    resp["level"] = level_query

    return jsonify(resp)

if __name__ == '__main__':
    app.run()

from flask import Flask, request
app = Flask(__name__)

@app.route('/ubereats_review')
def ubereats_review():
