from flask import Flask, request, make_response

app = Flask(__name__)

@app.route('/set_viewed')
def set_viewed():
    resp = make_response('OK')
    if request.args.get('ad_id'):
        resp.set_cookie('ad{}-viewed'.format(request.args['ad_id']), 'true')
    return resp

if __name__ == '__main__':
    app.run()

