from flask import Flask, request, jsonify
app = Flask(__name__)

@app.route('/suggestions')
def suggestions():
    idea_1 = request.args.get('idea_1')
    idea_2 = request.args.get('idea_2')
    idea_3 = request.args.get('idea_3')

    response = {
        'idea_1': idea_1,
        'idea_2': idea_2,
        'idea_3': idea_3
    }
    return jsonify(response)
